import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        try {
            String s = br.readLine();
            int T = 1;
            while (T-- > 0) {
                if (s.length() == 1) {
                    if (s.equals("0") || s.equals("_") || s.equals("X")) {
                        System.out.println(1);
                    } else {
                        System.out.println(0);
                    }
                } else {
                    boolean hasX = false;
                    for (char c : s.toCharArray()) {
                        if (c == 'X') {
                            hasX = true;
                            break;
                        }
                    }
                    if (!hasX) {
                        System.out.println(compute(s));
                    } else {
                        int total = 0;
                        for (int d = 0; d <= 9; d++) {
                            String replaced = s.replace('X', (char) (d + '0'));
                            total += compute(replaced);
                        }
                        System.out.println(total);
                    }
                }
            }
        } catch (IOException e) {
            e.printStackTrace();
        }
    }

    public static int compute(String s) {
        int n = s.length();
        int p = s.charAt(0) != '0' ? 1 : 0;
        for (int i = 0; i < n - 2; i++) {
            if (s.charAt(i) == '_') {
                p *= (i == 0) ? 9 : 10;
            }
        }
        int p1 = 0;
        if (s.charAt(n - 1) == '_' && s.charAt(n - 2) == '_') {
            p1 = (n == 2) ? 3 : 4;
        } else if (s.charAt(n - 1) == '_') {
            if (s.charAt(n - 2) == '0' || s.charAt(n - 2) == '5' || s.charAt(n - 2) == '2' || s.charAt(n - 2) == '7') {
                p1 = 1;
            }
        } else if (s.charAt(n - 2) == '_') {
            if (s.charAt(n - 1) == '0') {
                p1 = (n == 2) ? 1 : 2;
            } else if (s.charAt(n - 1) == '5') {
                p1 = 2;
            }
        } else {
            int val = Integer.parseInt(s.substring(n - 2));
            if (val % 25 == 0) p1 = 1;
        }
        return p * p1;
    }
}
